import{_ as t,c as a,o as r,ag as i}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"AI & Autonomy","description":"","frontmatter":{"title":"AI & Autonomy"},"headers":[],"relativePath":"ai-ml/index.md","filePath":"ai-ml/index.md","lastUpdated":null}'),o={name:"ai-ml/index.md"};function n(l,e,s,d,h,m){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-autonomy" tabindex="-1">AI &amp; Autonomy <a class="header-anchor" href="#ai-autonomy" aria-label="Permalink to &quot;AI &amp; Autonomy&quot;">​</a></h1><p>Artificial intelligence, machine learning, large language models, and autonomous systems resources for defense and research applications.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>New to AI/ML? Start with these community guides:</p><table tabindex="0"><thead><tr><th>Resource</th><th>Description</th></tr></thead><tbody><tr><td><a href="/ai-ml/ai-ml-learning.html">AI/ML Learning Guide</a></td><td>Comprehensive introduction to AI and ML concepts</td></tr><tr><td><a href="/ai-ml/ai-prompting.html">AI Prompting Guide</a></td><td>Best practices for prompt engineering</td></tr><tr><td><a href="/ai-ml/ai-ethics.html">AI Ethics</a></td><td>Ethical considerations in AI development and deployment</td></tr></tbody></table><h2 id="large-language-models-llms" tabindex="-1">Large Language Models (LLMs) <a class="header-anchor" href="#large-language-models-llms" aria-label="Permalink to &quot;Large Language Models (LLMs)&quot;">​</a></h2><h3 id="government-military-llms" tabindex="-1">Government &amp; Military LLMs <a class="header-anchor" href="#government-military-llms" aria-label="Permalink to &quot;Government &amp; Military LLMs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Platform</th><th>Access</th><th>Notes</th></tr></thead><tbody><tr><td><a href="https://niprgpt.mil/" target="_blank" rel="noreferrer">NIPRGPT</a></td><td>NIPR</td><td>DoD-approved LLM for unclassified use</td></tr><tr><td><a href="https://chat.asksage.ai/" target="_blank" rel="noreferrer">AskSAGE</a></td><td>NIPR</td><td>AI assistant for government users</td></tr><tr><td>Higher Enclaves</td><td>Search &quot;AI on Government Systems&quot; on Intellipedia</td><td>Classified AI tools and resources</td></tr></tbody></table><h3 id="local-llms-run-on-your-hardware" tabindex="-1">Local LLMs (Run on Your Hardware) <a class="header-anchor" href="#local-llms-run-on-your-hardware" aria-label="Permalink to &quot;Local LLMs (Run on Your Hardware)&quot;">​</a></h3><ul><li><a href="https://lmstudio.ai/" target="_blank" rel="noreferrer">LM Studio</a> - Desktop app for MacOS (M1+), Windows, Linux. See <a href="/ai-ml/ai-prompting.html">AI Prompting Guide</a></li><li><a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a> - Command-line LLM runner. See <a href="/general/ollama.html">Ollama Guide</a></li><li><a href="/ai-ml/pi-llm.html">Pi LLM Guide</a> - Running LLMs on Raspberry Pi</li><li><a href="https://marketplace.visualstudio.com/items?itemName=Continue.continue" target="_blank" rel="noreferrer">Continue AI</a> - VS Code extension for AI-assisted coding with Ollama</li></ul><h3 id="commercial-llms" tabindex="-1">Commercial LLMs <a class="header-anchor" href="#commercial-llms" aria-label="Permalink to &quot;Commercial LLMs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Service</th><th>Link</th><th>Notes</th></tr></thead><tbody><tr><td>ChatGPT</td><td><a href="https://chatgpt.com" target="_blank" rel="noreferrer">chatgpt.com</a></td><td>OpenAI&#39;s GPT models</td></tr><tr><td>Gemini</td><td><a href="https://gemini.google.com" target="_blank" rel="noreferrer">gemini.google.com</a></td><td>Google&#39;s LLM (formerly Bard)</td></tr><tr><td>Claude</td><td><a href="https://claude.ai" target="_blank" rel="noreferrer">claude.ai</a></td><td>Anthropic&#39;s AI assistant</td></tr><tr><td>Perplexity</td><td><a href="https://perplexity.ai" target="_blank" rel="noreferrer">perplexity.ai</a></td><td>AI search with citations</td></tr></tbody></table><h2 id="ai-tools-applications" tabindex="-1">AI Tools &amp; Applications <a class="header-anchor" href="#ai-tools-applications" aria-label="Permalink to &quot;AI Tools &amp; Applications&quot;">​</a></h2><h3 id="content-generation" tabindex="-1">Content Generation <a class="header-anchor" href="#content-generation" aria-label="Permalink to &quot;Content Generation&quot;">​</a></h3><ul><li><a href="https://dreamstudio.ai/generate" target="_blank" rel="noreferrer">Dream Studio</a> - AI image generation (no login required)</li><li><a href="https://midjourney.com/" target="_blank" rel="noreferrer">Midjourney</a> - High-quality AI art generation</li><li><a href="https://ideogram.ai/" target="_blank" rel="noreferrer">Ideogram AI</a> - Creative AI tools</li><li><a href="https://perchance.org/ai-icon-generator" target="_blank" rel="noreferrer">AI Icon Generator</a> - Logo and icon generation</li></ul><h3 id="writing-coding" tabindex="-1">Writing &amp; Coding <a class="header-anchor" href="#writing-coding" aria-label="Permalink to &quot;Writing &amp; Coding&quot;">​</a></h3><ul><li><a href="https://writer.com/" target="_blank" rel="noreferrer">Writer</a> - AI writing assistant</li><li><a href="https://writer.com/ai-content-detector/" target="_blank" rel="noreferrer">AI Content Detector</a> - Detect AI-generated content</li><li><a href="https://github.com/features/copilot" target="_blank" rel="noreferrer">GitHub Copilot</a> - AI pair programming</li><li><a href="/ai-ml/hackergpt2.html">HackerGPT</a> - Security-focused AI assistant</li></ul><h3 id="ai-prompt-templates" tabindex="-1">AI Prompt Templates <a class="header-anchor" href="#ai-prompt-templates" aria-label="Permalink to &quot;AI Prompt Templates&quot;">​</a></h3><ul><li><a href="/ai-ml/award-bullet-ai-prompt-template.html">Award Bullet AI Prompt Template</a> - Generate military award bullets</li><li><a href="/ai-ml/evaluation-ai-prompt.html">Evaluation AI Prompt</a> - AI assistance for evaluations</li><li><a href="https://nordnet.blob.core.windows.net/bilde/20-Effective-ChatGPT-Prompts.pdf" target="_blank" rel="noreferrer">ChatGPT Prompt Templates</a> - 20 effective prompts</li></ul><h2 id="ai-resources-repositories" tabindex="-1">AI Resources &amp; Repositories <a class="header-anchor" href="#ai-resources-repositories" aria-label="Permalink to &quot;AI Resources &amp; Repositories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://doc.clickup.com/25598832/d/h/rd6vg-14247/0b79ca1dc0f7429/rd6vg-12207" target="_blank" rel="noreferrer">AI Master List</a></td><td>Comprehensive AI/LLM tools list</td></tr><tr><td><a href="https://github.com/mehmetkahya0/ai-catalog" target="_blank" rel="noreferrer">AI Catalog</a></td><td>Curated AI tools repository</td></tr><tr><td><a href="https://github.com/amusi/awesome-ai-awesomeness" target="_blank" rel="noreferrer">Awesome Generative AI</a></td><td>Generative AI resources</td></tr><tr><td><a href="https://futuretools.io" target="_blank" rel="noreferrer">FutureTools</a></td><td>Latest AI/ML tools and services</td></tr><tr><td><a href="https://chat.lmsys.org/?arena" target="_blank" rel="noreferrer">LLM Comparison</a></td><td>Leaderboard and ratings of LLMs</td></tr><tr><td><a href="https://playground.openai.com/" target="_blank" rel="noreferrer">GPT-3 Playground</a></td><td>Experiment with OpenAI models</td></tr></tbody></table><h2 id="autonomous-systems" tabindex="-1">Autonomous Systems <a class="header-anchor" href="#autonomous-systems" aria-label="Permalink to &quot;Autonomous Systems&quot;">​</a></h2><p>For unmanned and autonomous systems, see the dedicated section:</p><ul><li><a href="/general/unmanned-systems.html">Unmanned Systems</a> - sUAS, drones, robotics</li><li><a href="/general/fpv-suas.html">FPV sUAS</a> - First-person view drone operations</li><li><a href="/general/guide-to-unmanned-systems.html">Guide to Unmanned Systems</a> - Leader&#39;s guide</li></ul><h2 id="ai-terminology" tabindex="-1">AI Terminology <a class="header-anchor" href="#ai-terminology" aria-label="Permalink to &quot;AI Terminology&quot;">​</a></h2><h3 id="intelligence-types" tabindex="-1">Intelligence Types <a class="header-anchor" href="#intelligence-types" aria-label="Permalink to &quot;Intelligence Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>Artificial Intelligence (AI)</td><td>Non-biological intelligence</td></tr><tr><td>Narrow Intelligence</td><td>Ability to accomplish a narrow set of goals (e.g., chess, driving)</td></tr><tr><td>General Intelligence</td><td>Ability to accomplish virtually any goal, including learning</td></tr><tr><td>Artificial General Intelligence (AGI)</td><td>AI that can accomplish any cognitive task at least as well as humans</td></tr><tr><td>Superintelligence</td><td>General intelligence far beyond human level</td></tr></tbody></table><h3 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>Life 1.0</td><td>Biological stage - evolves hardware and software</td></tr><tr><td>Life 2.0</td><td>Cultural stage - evolves hardware, designs software</td></tr><tr><td>Life 3.0</td><td>Technological stage - designs both hardware and software</td></tr><tr><td>Intelligence Explosion</td><td>Recursive self-improvement leading to superintelligence</td></tr><tr><td>Friendly AI</td><td>Superintelligence with goals aligned with humanity</td></tr></tbody></table><p><em>Reference: Tegmark, M. (2017). Life 3.0: Being Human in the Age of Artificial Intelligence.</em></p><h2 id="community-content" tabindex="-1">Community Content <a class="header-anchor" href="#community-content" aria-label="Permalink to &quot;Community Content&quot;">​</a></h2><ul><li><a href="/ai-ml/ai-ml-community-content.html">AI/ML Community Content</a> - Community-contributed resources</li><li><a href="https://forum.irregularchat.com/tag/ai" target="_blank" rel="noreferrer">AI Discussions on Forum</a> - Community discussions</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/ai-ml/ai-resources.html">AI Resources</a> - Extended AI/ML resources list</li><li><a href="/ai-ml/training-event-survey.html">Training Event Survey</a> - AI-assisted training tools</li></ul>',34)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
